  1→{
  2→  "$schema": "./node_modules/@angular/cli/lib/config/schema.json",
  3→  "version": 1,
  4→  "cli": {
  5→    "packageManager": "npm"
  6→  },
  7→  "newProjectRoot": "projects",
  8→  "projects": {
  9→    "guitar-trainer": {
 10→      "projectType": "application",
 11→      "schematics": {
 12→        "@schematics/angular:component": {
 13→          "style": "scss"
 14→        }
 15→      },
 16→      "root": "",
 17→      "sourceRoot": "src",
 18→      "prefix": "app",
 19→      "i18n": {
 20→        "sourceLocale": "en",
 21→        "locales": {
 22→          "nl": "src/locale/messages.nl.xlf",
 23→          "de": "src/locale/messages.de.xlf"
 24→        }
 25→      },
 26→      "architect": {
 27→        "build": {
 28→          "builder": "@angular/build:application",
 29→          "options": {
 30→            "browser": "src/main.ts",
 31→            "tsConfig": "tsconfig.app.json",
 32→            "inlineStyleLanguage": "scss",
 33→            "assets": [
 34→              {
 35→                "glob": "**/*",
 36→                "input": "public"
 37→              }
 38→            ],
 39→            "styles": ["src/styles.scss"],
 40→            "polyfills": ["@angular/localize/init"]
 41→          },
 42→          "configurations": {
 43→            "production": {
 44→              "localize": true,
 45→              "budgets": [
 46→                {
 47→                  "type": "initial",
 48→                  "maximumWarning": "500kB",
 49→                  "maximumError": "1MB"
 50→                },
 51→                {
 52→                  "type": "anyComponentStyle",
 53→                  "maximumWarning": "4kB",
 54→                  "maximumError": "8kB"
 55→                }
 56→              ],
 57→              "outputHashing": "all"
 58→            },
 59→            "development": {
 60→              "optimization": false,
 61→              "extractLicenses": false,
 62→              "sourceMap": true
 63→            },
 64→            "nl": {
 65→              "localize": ["nl"],
 66→              "optimization": false,
 67→              "extractLicenses": false,
 68→              "sourceMap": true
 69→            },
 70→            "de": {
 71→              "localize": ["de"],
 72→              "optimization": false,
 73→              "extractLicenses": false,
 74→              "sourceMap": true
 75→            }
 76→          },
 77→          "defaultConfiguration": "production"
 78→        },
 79→        "serve": {
 80→          "builder": "@angular/build:dev-server",
 81→          "configurations": {
 82→            "production": {
 83→              "buildTarget": "guitar-trainer:build:production"
 84→            },
 85→            "development": {
 86→              "buildTarget": "guitar-trainer:build:development"
 87→            },
 88→            "nl": {
 89→              "buildTarget": "guitar-trainer:build:nl"
 90→            },
 91→            "de": {
 92→              "buildTarget": "guitar-trainer:build:de"
 93→            }
 94→          },
 95→          "defaultConfiguration": "development"
 96→        },
 97→        "extract-i18n": {
 98→          "builder": "@angular/build:extract-i18n",
 99→          "options": {
100→            "outputPath": "src/locale",
101→            "format": "xlf"
102→          }
103→        },
104→        "test": {
105→          "builder": "@angular/build:unit-test"
106→        }
107→      }
108→    }
109→  }
110→}
111→

 1→import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
 2→import { RouterOutlet } from '@angular/router';
 3→import { TuiRoot } from '@taiga-ui/core';
 4→import { ThemeService } from './theme';
 5→
 6→@Component({
 7→  selector: 'app-root',
 8→  imports: [RouterOutlet, TuiRoot],
 9→  templateUrl: './app.html',
10→  styleUrl: './app.scss',
11→  changeDetection: ChangeDetectionStrategy.OnPush,
12→})
13→export class AppComponent {
14→  protected readonly themeService = inject(ThemeService);
15→}
16→

 1→import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
 2→import { provideAnimationsAsync } from '@angular/platform-browser/animations/async';
 3→import { provideRouter } from '@angular/router';
 4→import { NG_EVENT_PLUGINS } from '@taiga-ui/event-plugins';
 5→
 6→import { routes } from './app.routes';
 7→
 8→export const appConfig: ApplicationConfig = {
 9→  providers: [
10→    provideBrowserGlobalErrorListeners(),
11→    provideAnimationsAsync(),
12→    provideRouter(routes),
13→    NG_EVENT_PLUGINS,
14→  ]
15→};
