import { defineConfig, devices } from '@playwright/test';
import { existsSync } from 'fs';
import { resolve } from 'path';

/**
 * Custom library path for VPS environments where Playwright browser
 * dependencies are installed in the user's home directory.
 * See: ~/playwright-libs/lib/
 */
const playwrightLibs = resolve(process.env['HOME'] ?? '', 'playwright-libs', 'lib');
const extraLdPath = existsSync(playwrightLibs) ? playwrightLibs : '';

function buildLaunchEnv(): Record<string, string> | undefined {
  if (!extraLdPath) return undefined;
  return {
    ...(process.env as Record<string, string>),
    LD_LIBRARY_PATH: [extraLdPath, process.env['LD_LIBRARY_PATH']].filter(Boolean).join(':'),
  };
}

export default defineConfig({
  testDir: './e2e',
  outputDir: './e2e/test-results',
  fullyParallel: true,
  forbidOnly: !!process.env['CI'],
  retries: process.env['CI'] ? 2 : 0,
  workers: process.env['CI'] ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'http://localhost:4200',
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    launchOptions: {
      env: buildLaunchEnv(),
    },
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
  webServer: {
    command: 'npm run start',
    url: 'http://localhost:4200',
    reuseExistingServer: !process.env['CI'],
    timeout: 120_000,
  },
});

